with remaining_keys as (select product_id from inventory except select product_id from inventory where quantity > 141), verified as (select s.* from inventory s inner join remaining_keys k on s.product_id = k.product_id) select date_trunc('year', last_restock) as year_start, product_id, store_id, count(distinct product_id) as distinct_product_ids, count(distinct store_id) as distinct_store_ids from verified group by cube (date_trunc('year', last_restock), product_id, store_id) having distinct_product_ids > 1 order by product_id
